const platformName = "remotive";

for (const item of $input.all()) {
  item.json.source = platformName;
}

return $input.all();

const rawData = $input.item.json.data;

const startMarker = '"description":"';
const endMarker = '","directApply"';

let jobDescription = "";

if (rawData.includes(startMarker) && rawData.includes(endMarker)) {
    jobDescription = rawData.split(startMarker)[1].split(endMarker)[0];

    jobDescription = jobDescription
        .replace(/\\n/g, ' ')        // Remove newlines
        .replace(/\\"/g, '"')        // Fix escaped quotes
        .replace(/<[^>]*>/g, ' ')    // Remove all HTML tags (<p>, <strong>, etc.)
        .replace(/&nbsp;/g, ' ')     // Fix spaces
        .replace(/&amp;/g, '&')      // Fix ampersands
        .replace(/\s+/g, ' ')        // Collapse extra white space
        .trim();
}

return {
    jobDescription: jobDescription
};

const html = $input.item.json.data;

const greenhouseRegex = /class=\"job__description body\">([\s\S]*?)<div class=\"divider\"/;
const match = html.match(greenhouseRegex);

let jobDescription = "";

if (match && match[1]) {
    jobDescription = match[1];

    jobDescription = jobDescription
        .replace(/<\/p>/g, '\n\n')
        .replace(/<\/li>/g, '\n')
        .replace(/<[^>]*>?/gm, '') // Remove all remaining tags
        .replace(/&nbsp;/g, ' ')   // Fix non-breaking spaces
        .replace(/&amp;/g, '&');   // Fix ampersands
}

return {
    jobDescription: jobDescription.trim()
};

const raw = $input.item.json.data || ""; 

return { 
    jobDescription: raw.split("Markdown Content:")[1]?.trim() || raw 
};

const html = $input.item.json.data || "";
const leverRegex = /<div[^>]*data-qa="job-description"[^>]*>([\s\S]*?)<div[^>]*data-qa="btn-apply-bottom"/i;
let match = html.match(leverRegex);

if (match && match[1]) {
    let cleanText = match[1];

    // Remove HTML tags, replacing them with newlines for block elements
    cleanText = cleanText.replace(/<(div|p|li|h3|h2)[^>]*>/gi, "\n");
    cleanText = cleanText.replace(/<[^>]*>/g, "");

    // Clean up escaped HTML entities
    cleanText = cleanText.replace(/&nbsp;/g, " ")
                         .replace(/&amp;/g, "&")
                         .replace(/&lt;/g, "<")
                         .replace(/&gt;/g, ">");

    // Remove excessive whitespace
    cleanText = cleanText.replace(/\n\s*\n/g, "\n\n").trim();

    return { jobDescription: cleanText };
}

